"""Add Owner-controlled room memories without rewriting existing rows or events."""
VERSION = 28
REQUIRED_COLUMNS = {'room_memory_entries': {'room_id', 'created_by', 'source_url', 'scope', 'deleted_at', 'content', 'source_snapshot', 'source_event_id', 'category', 'updated_at', 'source_seq', 'source_kind', 'target_agent_id', 'revision', 'memory_id', 'created_at', 'updated_by'}, 'room_memory_state': {'room_id', 'revision', 'common_context_after_seq'}, 'room_memory_agent_state': {'room_id', 'context_after_seq', 'legacy_memory_disabled', 'revision', 'agent_id'}, 'room_memory_commands': {'owner_id', 'room_id', 'response', 'idempotency_key', 'request_digest', 'created_at'}}


def upgrade(db):
    db.execute("CREATE TABLE room_memory_entries (\n\tmemory_id VARCHAR(36) NOT NULL, \n\troom_id INTEGER NOT NULL, \n\tcategory VARCHAR(16) NOT NULL, \n\tcontent TEXT NOT NULL, \n\tscope VARCHAR(8) NOT NULL, \n\ttarget_agent_id INTEGER, \n\tsource_kind VARCHAR(8) NOT NULL, \n\tsource_event_id VARCHAR(36), \n\tsource_seq INTEGER, \n\tsource_url VARCHAR(2048), \n\tsource_snapshot JSON NOT NULL, \n\trevision INTEGER NOT NULL, \n\tcreated_by INTEGER NOT NULL, \n\tupdated_by INTEGER NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tdeleted_at DATETIME, \n\tPRIMARY KEY (memory_id), \n\tFOREIGN KEY(room_id, target_agent_id) REFERENCES room_memberships (room_id, agent_id), \n\tFOREIGN KEY(source_event_id, room_id) REFERENCES room_events (event_id, room_id), \n\tCHECK (category IN ('fact','decision','requirement')), \n\tCHECK (length(content) BETWEEN 1 AND 2000 AND revision >= 1), \n\tCHECK ((scope='room' AND target_agent_id IS NULL) OR (scope='agent' AND target_agent_id IS NOT NULL)), \n\tCHECK ((source_kind='manual' AND source_event_id IS NULL AND source_seq IS NULL AND source_url IS NULL) OR (source_kind='event' AND source_event_id IS NOT NULL AND source_seq IS NOT NULL AND source_seq >= 1 AND source_url IS NULL) OR (source_kind='link' AND source_url IS NOT NULL AND source_event_id IS NULL AND source_seq IS NULL)), \n\tFOREIGN KEY(room_id) REFERENCES conversations (id), \n\tFOREIGN KEY(created_by) REFERENCES users (id), \n\tFOREIGN KEY(updated_by) REFERENCES users (id)\n)")
    db.execute('CREATE TABLE room_memory_state (\n\troom_id INTEGER NOT NULL, \n\trevision INTEGER NOT NULL, \n\tcommon_context_after_seq INTEGER NOT NULL, \n\tPRIMARY KEY (room_id), \n\tCHECK (revision >= 0 AND common_context_after_seq >= 0), \n\tFOREIGN KEY(room_id) REFERENCES conversations (id)\n)')
    db.execute('CREATE TABLE room_memory_agent_state (\n\troom_id INTEGER NOT NULL, \n\tagent_id INTEGER NOT NULL, \n\trevision INTEGER NOT NULL, \n\tcontext_after_seq INTEGER NOT NULL, \n\tlegacy_memory_disabled BOOLEAN NOT NULL, \n\tPRIMARY KEY (room_id, agent_id), \n\tFOREIGN KEY(room_id, agent_id) REFERENCES room_memberships (room_id, agent_id), \n\tCHECK (revision >= 0 AND context_after_seq >= 0)\n)')
    db.execute('CREATE TABLE room_memory_commands (\n\towner_id INTEGER NOT NULL, \n\tidempotency_key VARCHAR(200) NOT NULL, \n\troom_id INTEGER NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tresponse JSON NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tPRIMARY KEY (owner_id, idempotency_key), \n\tFOREIGN KEY(room_id, owner_id) REFERENCES conversations (id, user_id), \n\tCHECK (length(idempotency_key) BETWEEN 1 AND 200 AND length(request_digest)=64), \n\tFOREIGN KEY(owner_id) REFERENCES users (id)\n)')
    db.execute("CREATE INDEX ix_memory_room_active ON room_memory_entries(room_id,deleted_at,memory_id)")
